solution.ledger.zig:
const std = @import("std");

// Refactoring: parsing, ordering, money formatting and table alignment are independent.
pub const Currency = enum { usd, eur };
pub const Locale = enum { en_us, nl_nl };
pub const Entry = struct { year: u16, month: u8, day: u8, description: []const u8, change: i64 };
pub fn createEntry(date: []const u8, description: []const u8, change: i64) !Entry {
    if (date.len != 10 or date[4] != '-' or date[7] != '-') return error.InvalidDate;
    const year = std.fmt.parseInt(u16, date[0..4], 10) catch return error.InvalidDate;
    const month = std.fmt.parseInt(u8, date[5..7], 10) catch return error.InvalidDate;
    const day = std.fmt.parseInt(u8, date[8..10], 10) catch return error.InvalidDate;
    const leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0);
    const days: u8 = switch (month) {
        1, 3, 5, 7, 8, 10, 12 => 31,
        4, 6, 9, 11 => 30,
        2 => if (leap) 29 else 28,
        else => return error.InvalidDate,
    };
    if (year == 0 or day == 0 or day > days) return error.InvalidDate;
    return .{ .year = year, .month = month, .day = day, .description = description, .change = change };
}
fn less(_: void, left: Entry, right: Entry) bool {
    if (left.year != right.year) return left.year < right.year;
    if (left.month != right.month) return left.month < right.month;
    if (left.day != right.day) return left.day < right.day;
    if (left.change != right.change) return left.change < right.change;
    return std.mem.order(u8, left.description, right.description) == .lt;
}
fn charCount(text: []const u8) usize {
    var n: usize = 0;
    for (text) |c| if (c & 0xc0 != 0x80) {
        n += 1;
    };
    return n;
}
fn pad(out: *std.array_list.Managed(u8), text: []const u8, width: usize, right: bool) !void {
    const count = charCount(text);
    const spaces = width - @min(width, count);
    if (right) try out.appendNTimes(' ', spaces);
    try out.appendSlice(text);
    if (!right) try out.appendNTimes(' ', spaces);
}
fn money(allocator: std.mem.Allocator, currency: Currency, locale: Locale, change: i64) ![]u8 {
    const magnitude: u64 = if (change < 0) @as(u64, @intCast(-(change + 1))) + 1 else @intCast(change);
    const integer = try std.fmt.allocPrint(allocator, "{d}", .{magnitude / 100});
    defer allocator.free(integer);
    var number = std.array_list.Managed(u8).init(allocator);
    defer number.deinit();
    for (integer, 0..) |digit, i| {
        if (i > 0 and (integer.len - i) % 3 == 0) try number.append(if (locale == .en_us) ',' else '.');
        try number.append(digit);
    }
    try number.append(if (locale == .en_us) '.' else ',');
    try number.append(@as(u8, @intCast(magnitude % 100 / 10)) + '0');
    try number.append(@as(u8, @intCast(magnitude % 10)) + '0');
    const symbol = if (currency == .usd) "$" else "€";
    if (locale == .en_us) return std.fmt.allocPrint(allocator, "{s}{s}{s}{s}", .{ if (change < 0) "(" else "", symbol, number.items, if (change < 0) ")" else " " });
    return std.fmt.allocPrint(allocator, "{s} {s}{s} ", .{ symbol, if (change < 0) "-" else "", number.items });
}
pub fn formatEntries(allocator: std.mem.Allocator, currency: Currency, locale: Locale, entries: []const Entry) ![]u8 {
    var out = std.array_list.Managed(u8).init(allocator);
    errdefer out.deinit();
    const headers = if (locale == .en_us) [_][]const u8{ "Date", "Description", "Change" } else [_][]const u8{ "Datum", "Omschrijving", "Verandering" };
    try pad(&out, headers[0], 10, false);
    try out.appendSlice(" | ");
    try pad(&out, headers[1], 25, false);
    try out.appendSlice(" | ");
    try pad(&out, headers[2], 13, false);
    const sorted = try allocator.dupe(Entry, entries);
    defer allocator.free(sorted);
    std.mem.sort(Entry, sorted, {}, less);
    for (sorted) |entry| {
        try out.append('\n');
        const date = if (locale == .en_us) try std.fmt.allocPrint(allocator, "{d:0>2}/{d:0>2}/{d:0>4}", .{ entry.month, entry.day, entry.year }) else try std.fmt.allocPrint(allocator, "{d:0>2}-{d:0>2}-{d:0>4}", .{ entry.day, entry.month, entry.year });
        defer allocator.free(date);
        try out.appendSlice(date);
        try out.appendSlice(" | ");
        var description = entry.description;
        var short = std.array_list.Managed(u8).init(allocator);
        defer short.deinit();
        if (charCount(description) > 25) {
            var count: usize = 0;
            var end: usize = 0;
            while (end < description.len) : (end += 1) {
                if (description[end] & 0xc0 != 0x80) {
                    if (count == 22) break;
                    count += 1;
                }
            }
            try short.appendSlice(description[0..end]);
            try short.appendSlice("...");
            description = short.items;
        }
        try pad(&out, description, 25, false);
        try out.appendSlice(" | ");
        const amount = try money(allocator, currency, locale, entry.change);
        defer allocator.free(amount);
        try pad(&out, amount, 13, true);
    }
    return out.toOwnedSlice();
}

tests.test_ledger.zig:
const std = @import("std");
const t = std.testing;
const a = t.allocator;
const m = @import("ledger.zig");
test "test_empty_ledger" {
    const entries = [_]m.Entry{};
    const out = try m.formatEntries(a, .usd, .en_us, &entries);
    defer a.free(out);
    try t.expectEqualStrings("Date       | Description               | Change       ", out);
}
test "test_one_entry" {
    const entries = [_]m.Entry{try m.createEntry("2015-01-01", "Buy present", -1000)};
    const out = try m.formatEntries(a, .usd, .en_us, &entries);
    defer a.free(out);
    try t.expectEqualStrings("Date       | Description               | Change       \n01/01/2015 | Buy present               |      ($10.00)", out);
}
test "test_credit_and_debit" {
    const entries = [_]m.Entry{ try m.createEntry("2015-01-02", "Get present", 1000), try m.createEntry("2015-01-01", "Buy present", -1000) };
    const out = try m.formatEntries(a, .usd, .en_us, &entries);
    defer a.free(out);
    try t.expectEqualStrings("Date       | Description               | Change       \n01/01/2015 | Buy present               |      ($10.00)\n01/02/2015 | Get present               |       $10.00 ", out);
}
test "test_final_order_tie_breaker_is_change" {
    const entries = [_]m.Entry{ try m.createEntry("2015-01-01", "Something", 0), try m.createEntry("2015-01-01", "Something", -1), try m.createEntry("2015-01-01", "Something", 1) };
    const out = try m.formatEntries(a, .usd, .en_us, &entries);
    defer a.free(out);
    try t.expectEqualStrings("Date       | Description               | Change       \n01/01/2015 | Something                 |       ($0.01)\n01/01/2015 | Something                 |        $0.00 \n01/01/2015 | Something                 |        $0.01 ", out);
}
test "test_overlong_description_is_truncated" {
    const entries = [_]m.Entry{try m.createEntry("2015-01-01", "Freude schoner Gotterfunken", -123456)};
    const out = try m.formatEntries(a, .usd, .en_us, &entries);
    defer a.free(out);
    try t.expectEqualStrings("Date       | Description               | Change       \n01/01/2015 | Freude schoner Gotterf... |   ($1,234.56)", out);
}
test "test_euros" {
    const entries = [_]m.Entry{try m.createEntry("2015-01-01", "Buy present", -1000)};
    const out = try m.formatEntries(a, .eur, .en_us, &entries);
    defer a.free(out);
    try t.expectEqualStrings("Date       | Description               | Change       \n01/01/2015 | Buy present               |      (€10.00)", out);
}
test "test_dutch_locale" {
    const entries = [_]m.Entry{try m.createEntry("2015-03-12", "Buy present", 123456)};
    const out = try m.formatEntries(a, .usd, .nl_nl, &entries);
    defer a.free(out);
    try t.expectEqualStrings("Datum      | Omschrijving              | Verandering  \n12-03-2015 | Buy present               |   $ 1.234,56 ", out);
}
test "test_dutch_locale_and_euros" {
    const entries = [_]m.Entry{try m.createEntry("2015-03-12", "Buy present", 123456)};
    const out = try m.formatEntries(a, .eur, .nl_nl, &entries);
    defer a.free(out);
    try t.expectEqualStrings("Datum      | Omschrijving              | Verandering  \n12-03-2015 | Buy present               |   € 1.234,56 ", out);
}
test "test_dutch_negative_number_with_3_digits_before_decimal_point" {
    const entries = [_]m.Entry{try m.createEntry("2015-03-12", "Buy present", -12345)};
    const out = try m.formatEntries(a, .usd, .nl_nl, &entries);
    defer a.free(out);
    try t.expectEqualStrings("Datum      | Omschrijving              | Verandering  \n12-03-2015 | Buy present               |    $ -123,45 ", out);
}
test "test_american_negative_number_with_3_digits_before_decimal_point" {
    const entries = [_]m.Entry{try m.createEntry("2015-03-12", "Buy present", -12345)};
    const out = try m.formatEntries(a, .usd, .en_us, &entries);
    defer a.free(out);
    try t.expectEqualStrings("Date       | Description               | Change       \n03/12/2015 | Buy present               |     ($123.45)", out);
}
test "test_multiple_entries_on_same_date_ordered_by_description" {
    const entries = [_]m.Entry{ try m.createEntry("2015-01-01", "Get present", 1000), try m.createEntry("2015-01-01", "Buy present", -1000) };
    const out = try m.formatEntries(a, .usd, .en_us, &entries);
    defer a.free(out);
    try t.expectEqualStrings("Date       | Description               | Change       \n01/01/2015 | Buy present               |      ($10.00)\n01/01/2015 | Get present               |       $10.00 ", out);
}
